const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const STORE_KEY = 'bloquecraft-studio-v1';
const colorNames = {'#9b78ee':'Violeta','#f1a94e':'Naranja','#5cc995':'Verde','#4ea8de':'Azul','#e97683':'Rojo'};
const defaultState = {projectName:'Mi primer addon', type:'item', name:'Amatista brillante', id:'amatista_brillante', category:'items', color:'#9b78ee', description:'Un cristal antiguo que brilla con energía propia.', stackable:true, glow:false, edible:false, items:[]};
let state = loadState();
let activeFilter = 'all';
let selectedFile = 'bp-manifest';
let toastTimer;
function loadState(){try{return {...defaultState,...JSON.parse(localStorage.getItem(STORE_KEY)||'{}')}}catch{return {...defaultState}}}
function saveState(show=false){localStorage.setItem(STORE_KEY,JSON.stringify(state));$('#save-button').innerHTML='<span>✓</span> Guardado';if(show)toast('Proyecto guardado en este dispositivo');}
function toast(message){const el=$('#toast');el.innerHTML=`<span>✓</span><b>${escapeHtml(message)}</b>`;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function escapeHtml(text=''){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function slug(text){return text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9_]+/g,'_').replace(/^_+|_+$/g,'').slice(0,24)}
function typeLabel(type){return ({item:'OBJETO',block:'BLOQUE',entity:'CRIATURA'})[type]||'OBJETO'}
function typePlural(type){return ({item:'Objeto',block:'Bloque',entity:'Criatura'})[type]||'Objeto'}
function displayName(type){return ({item:'OBJETO PERSONALIZADO',block:'BLOQUE PERSONALIZADO',entity:'CRIATURA PERSONALIZADA'})[type]}
function syncInputs(){
 $('#project-name').value=state.projectName;$('#crumb-name').textContent=state.projectName||'Nuevo addon';
 $('#content-name').value=state.name;$('#content-id').value=state.id;$('#content-category').value=state.category;
 $('#content-description').value=state.description;$('#stackable').checked=state.stackable;$('#glow').checked=state.glow;$('#edible').checked=state.edible;
 $$('.type-option').forEach(b=>{b.classList.toggle('selected',b.dataset.type===state.type);b.setAttribute('aria-selected',b.dataset.type===state.type)});
 $$('.swatch').forEach(b=>b.classList.toggle('active',b.dataset.color===state.color));
 $('#color-label').textContent=colorNames[state.color]||'Personalizado';
 document.documentElement.style.setProperty('--object-color',state.color);
 $('#preview-name').textContent=state.name||'Tu creación';$('#preview-kind').textContent=displayName(state.type);
 $('#preview-id').textContent=`bc:${state.id||'identificador'}`;
 $('#char-count').textContent=state.description.length;
 const isEntity=state.type==='entity', isBlock=state.type==='block';
 $('#stackable').closest('label').style.display=isEntity||isBlock?'none':'';
 $('#glow').closest('label').style.display=isEntity?'none':'';
 $('#edible').closest('label').style.display=state.type==='item'?'':'none';
 const preview=$('#preview-object');preview.style.borderRadius=isBlock?'2px':isEntity?'35% 35% 8px 8px':'0';preview.style.clipPath=isBlock?'none':isEntity?'polygon(26% 0,74% 0,94% 18%,88% 73%,73% 73%,73% 100%,56% 100%,56% 74%,44% 74%,44% 100%,27% 100%,27% 74%,12% 74%,6% 18%)':'';
 $('#preview-object .object-shine').style.display=isBlock?'none':'';
 $('#item-count').textContent=`(${state.items.length})`;$('#nav-count').textContent=state.items.length;
 renderContent();renderFiles();
}
function renderContent(){
 const list=$('#content-list');
 if(!state.items.length){list.innerHTML='<div class="empty-state"><span class="empty-state-icon">＋</span><span><b>Tu mundo, tus reglas.</b><small>Añade tu primera creación con el formulario de arriba.</small></span></div>'}
 else list.innerHTML=state.items.slice(-3).reverse().map((item,i)=>`<div class="content-row"><span class="item-swatch" style="--item-color:${item.color}">${item.type==='block'?'▦':item.type==='entity'?'♟':'◆'}</span><span><b>${escapeHtml(item.name)}</b><small>bc:${escapeHtml(item.id)} · ${typeLabel(item.type)}</small></span><span class="row-type">${typeLabel(item.type)}</span><button class="row-delete" data-delete="${state.items.length-1-i}" aria-label="Eliminar ${escapeHtml(item.name)}">×</button></div>`).join('');
 list.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeItem(Number(b.dataset.delete)));
 renderGrid();
}
function renderGrid(){
 const grid=$('#content-grid');if(!grid)return;
 const term=($('#search-content')?.value||'').trim().toLowerCase();
 const filtered=state.items.filter(it=>(activeFilter==='all'||it.type===activeFilter)&&(!term||`${it.name} ${it.id}`.toLowerCase().includes(term)));
 $('#filter-all-count').textContent=state.items.length;
 if(!filtered.length){grid.innerHTML=`<div class="empty-grid"><span>✦</span><b>${state.items.length?'No hay resultados':'Tu biblioteca está esperando una idea'}</b><small>${state.items.length?'Prueba con otro término o filtro.':'Crea un objeto, bloque o criatura desde el diseñador.'}</small></div>`;return}
 grid.innerHTML=filtered.map(it=>`<article class="content-card"><div class="card-art"><span class="card-object" style="--item-color:${it.color};${it.type==='block'?'clip-path:none;border-radius:2px':''}"></span></div><div class="card-meta"><span class="item-swatch" style="--item-color:${it.color};width:28px;height:28px;font-size:14px">${it.type==='block'?'▦':it.type==='entity'?'♟':'◆'}</span><span><b>${escapeHtml(it.name)}</b><small>bc:${escapeHtml(it.id)} · ${typeLabel(it.type)}</small></span><button class="card-delete" data-id="${escapeHtml(it.id)}" title="Eliminar">×</button></div></article>`).join('');
 grid.querySelectorAll('.card-delete').forEach(b=>b.onclick=()=>removeItem(state.items.findIndex(i=>i.id===b.dataset.id)));
}
function removeItem(index){if(index<0)return;const removed=state.items.splice(index,1)[0];saveState();syncInputs();toast(`${removed.name} eliminado`)}
function addItem(){
 const name=$('#content-name').value.trim(), id=slug($('#content-id').value);
 if(!name){$('#content-name').focus();toast('Escribe un nombre para tu creación');return}
 if(!id){$('#content-id').focus();toast('Añade un identificador válido');return}
 if(state.items.some(i=>i.id===id)){toast('Ese identificador ya existe en tu proyecto');$('#content-id').focus();return}
 const item={type:state.type,name,id,category:state.category,color:state.color,description:$('#content-description').value.trim(),stackable:$('#stackable').checked,glow:$('#glow').checked,edible:$('#edible').checked};
 state.items.push(item);state.id=slug(id);saveState();syncInputs();toast(`${name} añadido al proyecto`);
}
function useTemplate(template){
 if(template==='gem')Object.assign(state,{type:'item',name:'Cristal mágico',id:'cristal_magico',category:'items',color:'#9b78ee',description:'Un cristal antiguo que brilla en la oscuridad.',stackable:true,glow:true,edible:false});
 if(template==='food')Object.assign(state,{type:'item',name:'Fruta del bosque',id:'fruta_del_bosque',category:'food',color:'#e97683',description:'Una fruta silvestre dulce y muy nutritiva.',stackable:true,glow:false,edible:true});
 if(template==='block')Object.assign(state,{type:'block',name:'Bloque de musgo',id:'bloque_de_musgo',category:'nature',color:'#5cc995',description:'Un bloque suave cubierto de musgo luminoso.',stackable:true,glow:false,edible:false});
 $('#modal').classList.remove('open');saveState();syncInputs();document.querySelector('[data-view="designer"]').click();toast('Plantilla cargada. ¡Hazla tuya!');
}
function switchView(view){$$('.view').forEach(v=>v.classList.toggle('active-view',v.id===`view-${view}`));$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='files')renderFiles()}

function uuid(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
function ensurePackIds(){if(!state.bpUuid)state.bpUuid=uuid();if(!state.rpUuid)state.rpUuid=uuid();saveState()}
function packNames(){const base=(state.projectName||'Mi addon').trim().replace(/[\\/:*?"<>|]/g,'').slice(0,32)||'Mi addon';return{base,bp:`${base}_BP`,rp:`${base}_RP`}}
function packManifests(){ensurePackIds();const {base}=packNames();return{
 bp:{format_version:2,header:{name:`${base} · Comportamiento`,description:`Contenido de ${base}, creado con Bloquecraft Studio.`,uuid:state.bpUuid,version:[1,0,0],min_engine_version:[1,21,0]},modules:[{type:'data',uuid:uuid(),version:[1,0,0]}],dependencies:[{uuid:state.rpUuid,version:[1,0,0]}]},
 rp:{format_version:2,header:{name:`${base} · Recursos`,description:`Recursos visuales de ${base}, creado con Bloquecraft Studio.`,uuid:state.rpUuid,version:[1,0,0],min_engine_version:[1,21,0]},modules:[{type:'resources',uuid:uuid(),version:[1,0,0]}]}
}}
function itemJson(it){const comps={'minecraft:icon':{textures:{default:it.id}},'minecraft:max_stack_size':it.stackable?64:1,'minecraft:hand_equipped':false};if(it.glow)comps['minecraft:glint']=true;if(it.edible)comps['minecraft:food']={nutrition:4,saturation_modifier:'normal',can_always_eat:true};return{format_version:'1.21.0',"minecraft:item":{description:{identifier:`bc:${it.id}`,menu_category:{category:it.category||'items'}},components:comps}}}
function blockJson(it){const comps={'minecraft:geometry':'minecraft:geometry.full_block','minecraft:material_instances':{'*':{texture:it.id,render_method:'opaque'}},'minecraft:destructible_by_mining':{seconds_to_destroy:1.5},'minecraft:map_color':it.color};if(it.glow)comps['minecraft:light_emission']=8;return{format_version:'1.21.80',"minecraft:block":{description:{identifier:`bc:${it.id}`,menu_category:{category:it.category==='nature'?'nature':'construction'}},components:comps}}}
function entityBehavior(it){return{format_version:'1.21.0',"minecraft:entity":{description:{identifier:`bc:${it.id}`,is_spawnable:true,is_summonable:true,is_experimental:false},components:{'minecraft:type_family':{family:['${it.id}','mob']},'minecraft:health':{value:20,max:20},'minecraft:movement':{value:0.25},'minecraft:navigation.walk':{can_path_over_water:true,avoid_water:false},'minecraft:movement.basic':{},'minecraft:jump.static':{},'minecraft:collision_box':{width:0.6,height:1.8},'minecraft:physics':{},'minecraft:pushable':{is_pushable:true,is_pushable_by_piston:true},'minecraft:follow_range':{value:16},'minecraft:nameable':{}}}}}
function entityGeometry(it){const geom=`geometry.bc.${it.id}`;return{format_version:'1.12.0',"minecraft:geometry":[{description:{identifier:geom,texture_width:16,texture_height:16,visible_bounds_width:2,visible_bounds_height:2,visible_bounds_offset:[0,1,0]},bones:[{name:'body',pivot:[0,12,0],cubes:[{origin:[-4,6,-2],size:[8,12,4],uv:[0,0]}]},{name:'head',pivot:[0,18,0],cubes:[{origin:[-4,18,-4],size:[8,8,8],uv:[0,0]}]},{name:'left_leg',pivot:[2,6,0],cubes:[{origin:[1,0,-2],size:[3,6,4],uv:[0,0]}]},{name:'right_leg',pivot:[-2,6,0],cubes:[{origin:[-4,0,-2],size:[3,6,4],uv:[0,0]}]}]}]}}
function buildTextFiles(){
 const manifests=packManifests(),{bp,rp}=packNames(), files={};
 files[`${bp}/manifest.json`]=JSON.stringify(manifests.bp,null,2);files[`${rp}/manifest.json`]=JSON.stringify(manifests.rp,null,2);
 const items=state.items.filter(it=>it.type==='item'),blocks=state.items.filter(it=>it.type==='block'),entities=state.items.filter(it=>it.type==='entity');
 items.forEach(it=>files[`${bp}/items/${it.id}.json`]=JSON.stringify(itemJson(it),null,2));
 blocks.forEach(it=>files[`${bp}/blocks/${it.id}.json`]=JSON.stringify(blockJson(it),null,2));
 entities.forEach(it=>files[`${bp}/entities/${it.id}.json`]=JSON.stringify(entityBehavior(it),null,2));
 files[`${rp}/textures/item_texture.json`]=JSON.stringify({resource_pack_name:rp,texture_name:'atlas.items',texture_data:Object.fromEntries(items.map(it=>[it.id,{textures:`textures/items/${it.id}`}]))},null,2);
 files[`${rp}/textures/terrain_texture.json`]=JSON.stringify({resource_pack_name:rp,texture_name:'atlas.terrain',padding:8,num_mipชaps:4,texture_data:Object.fromEntries(blocks.map(it=>[it.id,{textures:`textures/blocks/${it.id}`}]))},null,2).replace('num_mipชaps','num_mip_levels');
 entities.forEach(it=>{
  const geom=`geometry.bc.${it.id}`;
  files[`${rp}/entity/${it.id}.entity.json`]=JSON.stringify({format_version:'1.10.0',"minecraft:client_entity":{description:{identifier:`bc:${it.id}`,materials:{default:'entity_alphatest'},textures:{default:`textures/entity/${it.id}`},geometry:{default:geom},render_controllers:[`controller.render.bc.${it.id}`]}}},null,2);
  files[`${rp}/models/entity/${it.id}.geo.json`]=JSON.stringify(entityGeometry(it),null,2);
  files[`${rp}/render_controllers/${it.id}.render_controllers.json`]=JSON.stringify({format_version:'1.8.0',render_controllers:{[`controller.render.bc.${it.id}`]:{geometry:'Geometry.default',materials:[{'*':'Material.default'}],textures:['Texture.default']}}},null,2);
 });
 return files;
}
function renderFiles(){
 const files=buildTextFiles(),tree=$('#file-tree');if(!tree)return;
 const keys=Object.keys(files).sort((a,b)=>{if(a.includes('manifest'))return -1;if(b.includes('manifest'))return 1;return a.localeCompare(b)});
 tree.innerHTML=keys.map((path,i)=>{const parts=path.split('/'),depth=parts.length-1,filename=parts.at(-1),isManifest=filename==='manifest.json';return `<div class="tree-row ${depth?'indent':''} ${selectedFile===path?'selected':''}" data-file="${escapeHtml(path)}" style="padding-left:${7+Math.max(0,depth-1)*12}px"><span class="tree-chevron">${depth?'':'⌄'}</span><span class="${isManifest?'tree-json':'tree-folder'}">${isManifest?'{}':filename.endsWith('.json')?'{}':'▰'}</span>${escapeHtml(filename)}</div>`}).join('');
 tree.querySelectorAll('.tree-row').forEach(row=>row.onclick=()=>{selectedFile=row.dataset.file;renderFiles()});
 const chosen=files[selectedFile]||files[keys[0]]||'{}';if(!files[selectedFile])selectedFile=keys[0]||'manifest.json';
 $('#code-file-name').textContent=selectedFile.split('/').slice(-2).join('/');$('#code-preview code').textContent=chosen;
}

