function makeTexture(color,seed,entity=false){
 const canvas=document.createElement('canvas');canvas.width=canvas.height=16;const ctx=canvas.getContext('2d');
 const base=color;ctx.fillStyle=base;ctx.fillRect(0,0,16,16);
 let hash=0;for(const c of seed)hash=(hash*31+c.charCodeAt(0))>>>0;
 for(let y=0;y<16;y++)for(let x=0;x<16;x++){hash=(hash*1664525+1013904223)>>>0;if((hash>>>29)>5){ctx.fillStyle=(hash&1)?'rgba(255,255,255,.17)':'rgba(24,40,28,.12)';ctx.fillRect(x,y,1,1)}}
 if(entity){ctx.fillStyle='rgba(255,255,255,.55)';ctx.fillRect(4,4,2,2);ctx.fillRect(10,4,2,2);ctx.fillStyle='#26352a';ctx.fillRect(5,5,1,1);ctx.fillRect(10,5,1,1)}
 return new Promise(resolve=>canvas.toBlob(blob=>blob.arrayBuffer().then(buf=>resolve(new Uint8Array(buf))),'image/png'));
}
function crc32(bytes){let crc=-1;for(const byte of bytes){crc^=byte;for(let j=0;j<8;j++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return(crc^-1)>>>0}
function zipStore(files){
 const encoder=new TextEncoder(),locals=[],centrals=[];let offset=0;
 for(const [name,data] of Object.entries(files)){
  const nameBytes=encoder.encode(name),bytes=typeof data==='string'?encoder.encode(data):data,crc=crc32(bytes);
  const local=new Uint8Array(30+nameBytes.length+bytes.length),lv=new DataView(local.buffer);
  lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint16(8,0,true);lv.setUint16(10,0,true);lv.setUint16(12,0,true);lv.setUint32(14,crc,true);lv.setUint32(18,bytes.length,true);lv.setUint32(22,bytes.length,true);lv.setUint16(26,nameBytes.length,true);lv.setUint16(28,0,true);local.set(nameBytes,30);local.set(bytes,30+nameBytes.length);locals.push(local);
  const central=new Uint8Array(46+nameBytes.length),cv=new DataView(central.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(10,0,true);cv.setUint16(12,0,true);cv.setUint16(14,0,true);cv.setUint32(16,crc,true);cv.setUint32(20,bytes.length,true);cv.setUint32(24,bytes.length,true);cv.setUint16(28,nameBytes.length,true);cv.setUint16(30,0,true);cv.setUint16(32,0,true);cv.setUint16(34,0,true);cv.setUint16(36,0,true);cv.setUint32(38,0,true);cv.setUint32(42,offset,true);central.set(nameBytes,46);centrals.push(central);offset+=local.length;
 }
 const centralSize=centrals.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),dv=new DataView(end.buffer);dv.setUint32(0,0x06054b50,true);dv.setUint16(4,0,true);dv.setUint16(6,0,true);dv.setUint16(8,centrals.length,true);dv.setUint16(10,centrals.length,true);dv.setUint32(12,centralSize,true);dv.setUint32(16,offset,true);dv.setUint16(20,0,true);
 const total=offset+centralSize+22,out=new Uint8Array(total);let pos=0;for(const a of locals){out.set(a,pos);pos+=a.length}for(const a of centrals){out.set(a,pos);pos+=a.length}out.set(end,pos);return out;
}
async function exportAddon(){
 if(!state.items.length){toast('Añade al menos un objeto, bloque o criatura antes de exportar');switchView('designer');$('#content-name').focus();return}
 const {bp,rp,base}=packNames(), files={...buildTextFiles()};
 for(const it of state.items){
  const folder=it.type==='item'?'items':it.type==='block'?'blocks':'entity';
  if(it.type==='item')files[`${rp}/textures/items/${it.id}.png`]=await makeTexture(it.color,it.id);
  if(it.type==='block')files[`${rp}/textures/blocks/${it.id}.png`]=await makeTexture(it.color,it.id);
  if(it.type==='entity')files[`${rp}/textures/entity/${it.id}.png`]=await makeTexture(it.color,it.id,true);
 }
