.template-options button{height:57px;border:1px solid #e8ede8;background:#fff;border-radius:6px;display:flex;align-items:center;gap:10px;padding:7px;text-align:left;color:#718076}
.template-options button:hover{border-color:#82b68c;background:#f7fbf7}
.template-options b{display:block;color:#435148;font-size:10px}
.template-options small{display:block;color:#9ba59e;font-size:8px;margin-top:4px}
.template-options button>span:last-child{margin-left:auto;font-size:15px}
