}

function renderAiSettings() {
  const mode = $('#ai-mode');
  if (!mode) return;
  mode.value = state.aiMode;
  $('#ai-endpoint').value = state.aiMode === 'ollama' && state.aiEndpoint === defaultState.aiEndpoint
