const { chromium } = require(process.env.HOME + '/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 1000 }, acceptDownloads: true });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  page.on('response', r => { if (r.status() >= 400 && r.url().startsWith('http://127.0.0.1:8123')) errors.push('HTTP ' + r.status() + ' ' + r.url()); });

  await page.goto('http://127.0.0.1:8123/', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');

  console.log('TITLE:', await page.title());
  console.log('AI ENGINE:', await page.evaluate(() => window.BloquecraftAI && window.BloquecraftAI.engineVersion));
  console.log('EXAMPLES:', await page.locator('#ai-examples .ai-example').count());
  console.log('INITIAL TOAST ERRORS:', errors);

  // Use local engine for deterministic test.
  await page.selectOption('#ai-mode', 'local');
  await page.fill('#ai-prompt', 'Crea una espada de escarcha con receta, un bloque de cristal lunar que ilumine la noche y un golem hostil que patrulle la nieve.');
  await page.click('#ai-generate');
  await page.waitForFunction(() => document.querySelectorAll('#content-list .content-row').length >= 3, null, { timeout: 20000 });
  await page.waitForTimeout(700);
  console.log('TOAST:', await page.locator('#toast').innerText());
  console.log('ITEM COUNT:', await page.locator('#item-count').innerText());
  console.log('PROJECT NAME:', await page.inputValue('#project-name'));
  const generated = await page.evaluate(() => JSON.parse(localStorage.getItem('bloquecraft-studio-v1')).items.map(i => ({ type: i.type, kind: i.kind, id: i.id, name: i.name, damage: i.damage, health: i.health, light: i.light })));
  console.log('GENERATED:', JSON.stringify(generated, null, 2));
  await page.screenshot({ path: '/tmp/opencode/shot-designer.png', fullPage: true });

  // Library view
  await page.click('[data-view="content"]');
  await page.waitForTimeout(200);
  console.log('CARDS:', await page.locator('.content-card').count());
