  await page.locator('#content-list .row-delete').first().click();
  await page.waitForTimeout(1000);
  console.log('after state', await page.evaluate(() => JSON.parse(localStorage.getItem('bloquecraft-studio-v1')).items.map(i => i.name)));
  console.log('count', await page.locator('#item-count').innerText());
  console.log('toast', await page.locator('#toast').innerText());
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

