const { chromium } = require(process.env.HOME + '/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const logs = [];
  page.on('console', m => logs.push(m.type() + ': ' + m.text()));
  page.on('requestfailed', r => logs.push('REQFAIL: ' + r.url().slice(0, 120) + ' ' + r.failure()?.errorText));
  page.on('response', r => { if (r.url().includes('pollinations')) logs.push('RESP ' + r.status() + ' ' + r.url()); });
  await page.goto('http://127.0.0.1:8123/');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.waitForTimeout(300);
  await page.fill('#ai-prompt', 'Crea una manzana lunar que brille, un bloque de cristal que ilumine la noche y un guardián neutral.');
  const t0 = Date.now();
  await page.click('#ai-generate');
  await page.waitForFunction(() => document.querySelectorAll('#content-list .content-row').length >= 1, null, { timeout: 80000 });
  await page.waitForTimeout(1000);
  console.log('ELAPSED', Date.now() - t0, 'ms');
  console.log('TOAST', await page.locator('#toast').innerText());
  console.log('ITEMS', await page.evaluate(() => JSON.parse(localStorage.getItem('bloquecraft-studio-v1')).items.map(i => [i.type, i.kind, i.name, i.id])));
  console.log('LOGS', logs.filter(l => !l.startsWith('log:')).slice(0, 20));
  await browser.close();
})().catch(e => { console.error('FAIL', e.message); process.exit(1); });

const { chromium } = require(process.env.HOME + '/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 1000 }, acceptDownloads: true });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://127.0.0.1:8123/');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  await page.click('#ai-settings-toggle');
  await page.selectOption('#ai-mode', 'local');
  await page.fill('#ai-prompt', 'Crea una espada de escarcha con receta, un bloque de cristal lunar que ilumine la noche y un golem hostil que patrulle la nieve.');
  await page.click('#ai-generate');
  await page.waitForFunction(() => document.querySelectorAll('#content-list .content-row').length >= 3);
  await page.waitForTimeout(400);
  await page.click('[data-view="designer"]');
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/opencode/shot-designer-full.png', fullPage: true });

  // Open template modal screenshot
  await page.click('#template-button');
  await page.waitForTimeout(250);
  await page.screenshot({ path: '/tmp/opencode/shot-templates.png' });
  await page.click('#modal-close');

  // Template sword (should now be unique and add)
  await page.click('#template-button');
  await page.click('[data-template="sword"]');
  await page.waitForTimeout(300);
  console.log('SWORD:', await page.inputValue('#content-name'), await page.inputValue('#content-id'));
  await page.click('#create-button');
  await page.waitForTimeout(300);
  console.log('COUNT AFTER SWORD:', await page.locator('#item-count').innerText());

  // Template entity
  await page.click('#template-button');
  await page.click('[data-template="entity"]');
  await page.waitForTimeout(300);
  console.log('ENTITY:', await page.inputValue('#content-name'), await page.inputValue('#content-id'));
  await page.click('#create-button');
  await page.waitForTimeout(300);
  console.log('COUNT AFTER ENTITY:', await page.locator('#item-count').innerText());

  // Delete one
  const before = await page.locator('#item-count').innerText();
  await page.locator('#content-list .row-delete').first().click();
  await page.waitForTimeout(400);
  console.log('DELETE:', before, '->', await page.locator('#item-count').innerText());

  // Files + export final
  await page.click('[data-view="files"]');
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/opencode/shot-files.png', fullPage: true });
  const [download] = await Promise.all([page.waitForEvent('download'), page.click('#export-button-files')]);
  await download.saveAs('/tmp/opencode/export-final.mcaddon');
  console.log('EXPORT:', download.suggestedFilename());
  await page.waitForTimeout(500);
  console.log('TOAST:', (await page.locator('#toast').innerText()).replace(/\n/g, ' | '));
  console.log('ERRORS:', errors.length ? errors : 'none');

  // Mobile
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await mobile.goto('http://127.0.0.1:8123/');
  await mobile.waitForTimeout(800);
  await mobile.screenshot({ path: '/tmp/opencode/shot-mobile.png', fullPage: true });
  console.log('MOBILE SCROLL WIDTH:', await mobile.evaluate(() => ({ scroll: document.documentElement.scrollWidth, client: document.documentElement.clientWidth })));
  await browser.close();
})().catch(e => { console.error('FAIL', e); process.exit(1); });

