const { chromium } = require(process.env.HOME + '/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1100 }, acceptDownloads: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://127.0.0.1:8123/');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.waitForTimeout(300);

  // Initial gem: no attributes
  console.log('ATTR initial hidden:', await page.locator('#attribute-block').isHidden());

  // Weapon manual
  await page.fill('#content-name', 'Espada de prueba');
  await page.waitForTimeout(200);
  console.log('ATTR sword labels:', await page.locator('#attribute-fields .attribute-field span').allInnerTexts());
  console.log('ATTR sword values:', await page.locator('#attribute-fields input').evaluateAll(inp => inp.map(i => [i.dataset.attribute, i.value])));
  await page.fill('[data-attribute="damage"]', '12');
  await page.fill('[data-attribute="durability"]', '800');
  await page.fill('#content-id', 'espada_de_prueba');
  await page.click('#create-button');
  await page.waitForTimeout(300);
  console.log('WEAPON CREATED:', await page.evaluate(() => { const i = JSON.parse(localStorage.getItem('bloquecraft-studio-v1')).items[0]; return { name: i.name, kind: i.kind, damage: i.damage, durability: i.durability }; }));

  // Block manual
  await page.click('.type-option[data-type="block"]');
  await page.waitForTimeout(200);
  console.log('ATTR block labels:', await page.locator('#attribute-fields .attribute-field span').allInnerTexts());
  await page.fill('#content-name', 'Ladrillo de prueba');
  await page.fill('#content-id', 'ladrillo_de_prueba');
  await page.fill('[data-attribute="light"]', '8');
  await page.fill('[data-attribute="hardness"]', '4.5');
  await page.click('#create-button');
  await page.waitForTimeout(300);
  console.log('BLOCK CREATED:', await page.evaluate(() => { const i = JSON.parse(localStorage.getItem('bloquecraft-studio-v1')).items.at(-1); return { name: i.name, kind: i.kind, hardness: i.hardness, light: i.light, explosion: i.explosion }; }));

  // Entity manual
