cd /tmp/opencode && node - <<'JS'
const { chromium } = require(process.env.HOME + '/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1440,height:1100}});
 await page.goto('http://127.0.0.1:8123/');
 await page.evaluate(()=>localStorage.clear());
 await page.reload();
 await page.waitForTimeout(300);
 await page.fill('#content-name','Espada de prueba');
 await page.waitForTimeout(200);
 const loc=page.locator('[data-attribute="damage"]');
 await loc.scrollIntoViewIfNeeded();
 await page.evaluate(()=>{const el=document.querySelector('[data-attribute="damage"]');window.__ref=el; window.__log=[]; el.addEventListener('focus',()=>window.__log.push('focus')); el.addEventListener('blur',()=>window.__log.push('blur')); el.addEventListener('input',()=>window.__log.push('input')); el.addEventListener('change',()=>window.__log.push('change')); el.addEventListener('click',()=>window.__log.push('click'));});
 await loc.click();
 await page.waitForTimeout(300);
 console.log(await page.evaluate(()=>({log:window.__log, same:document.querySelector('[data-attribute="damage"]')===window.__ref, contains:document.contains(window.__ref), active:document.activeElement.tagName+'#'+document.activeElement.id, html:document.querySelector('[data-attribute="damage"]')?.outerHTML})));
 await browser.close();
})()
