  if (button) button.querySelector('b').textContent = busy ? 'Creando tu addon...' : 'Generar addon completo';
  if (busy && $('#ai-generate-hint')) $('#ai-generate-hint').textContent = 'Diseñando objetos, texturas y archivos...';
  renderAiSettings();
}

