const { chromium } = require(process.env.HOME + '/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto('http://127.0.0.1:8123/');
  const prompts = [
    'Crea una espada de escarcha, un bloque de cristal lunar que ilumine la noche y un golem hostil que patrulle la nieve.',
    'Una manzana lunar que brille en la oscuridad y un hacha de obsidiana.',
    'Un perro mascota amigable, un ciervo pasivo y un lobo neutral que protege el bosque.',
    'Un bloque de piedra rúnica, un ladrillo de magma que ilumine y una poción de prueba.',
    'Un dragón hostil, una armadura de amatista y un cristal de vacío que brille.'
  ];
  for (const prompt of prompts) {
    const result = await page.evaluate((p) => window.BloquecraftAI.generate(p), prompt);
    console.log('PROMPT:', prompt);
    console.log('NAME:', result.projectName);
    for (const i of result.items) console.log(' ', i.type, i.kind, '|', i.id, '|', i.name, '|', i.description, '|', { dmg: i.damage, dur: i.durability, hp: i.health, light: i.light, food: i.edible, glow: i.glow });
  }
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

