from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json

CONTENT = """```json
{
  "projectName": "Forja Externa",
  "items": [
    {
      "type": "item", "kind": "sword", "name": "Hoja de prueba", "id": "hoja_de_prueba",
      "color": "#3fa9f5", "description": "Una hoja creada por la API externa de prueba.",
      "damage": 15, "durability": 900, "cooldown": 0.6, "rarity": "rare", "glow": true,
      "recipe": true, "ingredient": "minecraft:diamond"
    },
    {
      "type": "block", "kind": "block", "name": "Bloque externo", "id": "bloque_externo",
      "color": "#6f42c1", "description": "Un bloque luminoso creado por la API externa.",
      "hardness": 3.5, "light": 12, "explosion": 8, "sound": "glass",
      "recipe": true, "ingredient": "minecraft:amethyst_shard"
    },
    {
      "type": "entity", "kind": "hostile", "name": "Golem externo", "id": "golem_externo",
      "color": "#d8a63a", "description": "Un golem hostil creado por la API externa.",
      "health": 80, "damage": 10, "speed": 0.3, "scale": 1.4, "spawn": true,
      "drop": "minecraft:gold_nugget"
    }
  ]
}
```"""

class Handler(BaseHTTPRequestHandler):
    def _cors(self):
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type, Authorization')
        self.send_header('Access-Control-Allow-Methods', 'POST, OPTIONS')
    def do_OPTIONS(self):
        self.send_response(204)
        self._cors()
        self.end_headers()
    def do_POST(self):
        length = int(self.headers.get('Content-Length', '0'))
        body = self.rfile.read(length).decode('utf-8', 'replace')
        try:
            request = json.loads(body)
            print('REQUEST', self.path, request.get('model'), len(request.get('messages', [])))
        except Exception:
            print('REQUEST', self.path, 'invalid json')
        payload = {
            'choices': [{
                'message': {'role': 'assistant', 'content': CONTENT}
            }]
        }
        data = json.dumps(payload).encode()
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self._cors()
        self.send_header('Content-Length', str(len(data)))
        self.end_headers()
        self.wfile.write(data)
    def log_message(self, *args):
