const { chromium } = require(process.env.HOME + '/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

function pngFixtures() {
  const dir = '/tmp/opencode/png-decode';
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
  execSync(`cd /tmp/opencode && rm -rf png-decode-ext && mkdir png-decode-ext && cd png-decode-ext && unzip -q ${process.argv[2] || 'export-final.mcaddon'} && find . -name '*.png' -print0 | xargs -0 -I{} cp {} ${dir}/ --parents`, { shell: '/bin/bash' });
  return execSync(`find ${dir} -name '*.png'`).toString().trim().split('\n').filter(Boolean).map((file) => ({
    name: path.basename(file),
    data: fs.readFileSync(file).toString('base64')
  }));
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 1100 }, acceptDownloads: true });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://127.0.0.1:8123/');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.waitForTimeout(300);

  // External OpenAI-compatible API.
  await page.click('#ai-settings-toggle');
  await page.selectOption('#ai-mode', 'custom');
  console.log('CUSTOM FIELDS VISIBLE:', await page.locator('#ai-custom-fields').isVisible());
  await page.fill('#ai-endpoint', 'http://127.0.0.1:8199/v1');
  await page.fill('#ai-model', 'mock-model');
  await page.fill('#ai-key', 'test-key');
  await page.fill('#ai-prompt', 'Crea una hoja, un bloque luminoso y un golem externo.');
  await page.click('#ai-generate');
  await page.waitForFunction(() => document.querySelectorAll('#content-list .content-row').length >= 3, null, { timeout: 30000 });
  await page.waitForTimeout(600);
  console.log('CLOUD TOAST:', (await page.locator('#toast').innerText()).replace(/\n/g, ' | '));
  console.log('CLOUD STATE:', JSON.stringify(await page.evaluate(() => {
    const s = JSON.parse(localStorage.getItem('bloquecraft-studio-v1'));
    return s.items.map((i) => ({ type: i.type, kind: i.kind, id: i.id, name: i.name, color: i.color, damage: i.damage, durability: i.durability, health: i.health, scale: i.scale, light: i.light }));
  }), null, 2));

  const [download] = await Promise.all([page.waitForEvent('download'), page.click('#export-button-content')]);
  await download.saveAs('/tmp/opencode/export-cloud.mcaddon');
  console.log('CLOUD EXPORT:', download.suggestedFilename());

  // Local generation twice from the same prompt: unique IDs and no duplicates.
  await page.selectOption('#ai-mode', 'local');
  const prompt = 'Una espada de hielo, un bloque de cristal lunar y un lobo neutral.';
  await page.fill('#ai-prompt', prompt);
  await page.click('#ai-generate');
  await page.waitForFunction(() => document.querySelectorAll('#content-list .content-row').length >= 6, null, { timeout: 20000 });
  await page.waitForTimeout(400);
  const afterFirst = await page.evaluate(() => JSON.parse(localStorage.getItem('bloquecraft-studio-v1')).items.map((i) => [i.id, i.name]));
  await page.fill('#ai-prompt', prompt);
  await page.click('#ai-generate');
  await page.waitForFunction(() => document.querySelectorAll('#content-list .content-row').length >= 9, null, { timeout: 20000 });
  await page.waitForTimeout(400);
  const afterSecond = await page.evaluate(() => JSON.parse(localStorage.getItem('bloquecraft-studio-v1')).items.map((i) => [i.id, i.name]));
  console.log('UNIQUE FIRST:', new Set(afterFirst.map((x) => x[0])).size === afterFirst.length, afterFirst.length);
  console.log('UNIQUE SECOND:', new Set(afterSecond.map((x) => x[0])).size === afterSecond.length, afterSecond.length);
  console.log('LAST 6:', afterSecond.slice(-6));

  // Offline auto mode -> local fallback.
  await page.selectOption('#ai-mode', 'auto');
  await context.setOffline(true);
  await page.fill('#ai-prompt', 'Un golem hostil de obsidiana y un bloque de magma que ilumine.');
  await page.click('#ai-generate');
  await page.waitForFunction(() => document.querySelectorAll('#content-list .content-row').length >= 11, null, { timeout: 20000 });
  await page.waitForTimeout(500);
  console.log('OFFLINE TOAST:', (await page.locator('#toast').innerText()).replace(/\n/g, ' | '));
  const onlineValue = await page.evaluate(() => navigator.onLine);
  console.log('NAVIGATOR ONLINE:', onlineValue);
  await context.setOffline(false);

  // Decode all exported PNGs in the browser.
  const fixtures = pngFixtures('/tmp/opencode/export-cloud.mcaddon');
  const decoded = await page.evaluate(async (files) => {
    const results = [];
    for (const file of files) {
      try {
        const binary = atob(file.data);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
        const bitmap = await createImageBitmap(new Blob([bytes], { type: 'image/png' }));
        results.push({ name: file.name, width: bitmap.width, height: bitmap.height });
      } catch (error) {
        results.push({ name: file.name, error: error.message });
      }
    }
    return results;
  }, fixtures);
  console.log('PNG DECODE:', decoded);
  console.log('ERRORS:', errors.length ? errors : 'none');

  await browser.close();
})().catch((error) => { console.error('FAILED', error); process.exit(1); });

