import json, re, sys, zipfile
from pathlib import Path

ARCHIVE = Path(sys.argv[1] if len(sys.argv) > 1 else '/tmp/opencode/export-final.mcaddon')
errors = []
warnings = []

with zipfile.ZipFile(ARCHIVE) as z:
    names = z.namelist()
    if z.testzip():
        errors.append('ZIP CRC failure')
    json_files = [n for n in names if n.endswith('.json')]
    parsed = {}
    for n in json_files:
        try:
            parsed[n] = json.loads(z.read(n))
        except Exception as exc:
            errors.append(f'Invalid JSON {n}: {exc}')
    if any(n.startswith('/') or '\\' in n for n in names):
        errors.append('Unsafe zip paths')
    if any('__MACOSX' in n for n in names):
        warnings.append('Contains __MACOSX files')

    top_dirs = sorted({n.split('/')[0] for n in names if '/' in n})
    bp_dirs = [d for d in top_dirs if d.endswith('_BP')]
    rp_dirs = [d for d in top_dirs if d.endswith('_RP')]
    if len(bp_dirs) != 1 or len(rp_dirs) != 1:
        errors.append(f'Expected one BP and one RP folder, got {top_dirs}')
        sys.exit(1)
    bp, rp = bp_dirs[0], rp_dirs[0]

    bp_manifest = parsed.get(f'{bp}/manifest.json')
    rp_manifest = parsed.get(f'{rp}/manifest.json')
    if not bp_manifest or not rp_manifest:
        errors.append('Missing manifests')
    else:
        if bp_manifest.get('format_version') != 2 or rp_manifest.get('format_version') != 2:
            errors.append('Manifest format_version is not 2')
        dep = bp_manifest.get('dependencies', [{}])[0].get('uuid')
        if dep != rp_manifest['header']['uuid']:
            errors.append('BP has no dependency on the RP UUID')
        if bp_manifest['header']['min_engine_version'] != rp_manifest['header']['min_engine_version']:
            errors.append('BP/RP min_engine_version mismatch')

    languages = parsed.get(f'{rp}/texts/languages.json')
    if languages is None:
        errors.append('Missing languages.json')
    lang_text = {}
    for lang in ('en_US', 'es_ES'):
        path = f'{rp}/texts/{lang}.lang'
        if path not in names:
            errors.append(f'Missing {lang}.lang')
        else:
            lang_text[lang] = z.read(path).decode('utf-8')
            for line in lang_text[lang].splitlines():
                if line and '=' not in line:
                    errors.append(f'{lang} line without =: {line!r}')

    item_atlas = parsed.get(f'{rp}/textures/item_texture.json', {}).get('texture_data', {})
    terrain_atlas = parsed.get(f'{rp}/textures/terrain_texture.json', {}).get('texture_data', {})

    def require_lang(key, label):
        for lang, text in lang_text.items():
            if f'{key}=' not in text:
                errors.append(f'Missing lang key {key} ({label}) in {lang}')

    def png_ok(path, width, height):
        if path not in names:
            errors.append(f'Missing texture {path}')
            return
        data = z.read(path)
        if not data.startswith(b'\x89PNG\r\n\x1a\n'):
            errors.append(f'Not a PNG: {path}')
            return
        w = int.from_bytes(data[16:20], 'big')
        h = int.from_bytes(data[20:24], 'big')
        if (w, h) != (width, height):
            errors.append(f'Unexpected size {w}x{h} for {path}')

    item_files = [n for n in names if re.fullmatch(rf'{re.escape(bp)}/items/[a-z0-9_]+\.json', n)]
    block_files = [n for n in names if re.fullmatch(rf'{re.escape(bp)}/blocks/[a-z0-9_]+\.json', n)]
    entity_files = [n for n in names if re.fullmatch(rf'{re.escape(bp)}/entities/[a-z0-9_]+\.json', n)]

    for n in item_files:
        data = parsed[n]
        desc = data['minecraft:item']['description']
        identifier = desc['identifier']
        namespace, item_id = identifier.split(':', 1)
        if namespace != 'bc':
            errors.append(f'Unexpected namespace {identifier}')
        components = data['minecraft:item']['components']
        if 'minecraft:icon' not in components:
            errors.append(f'{identifier} missing icon')
        else:
            shortname = components['minecraft:icon']['textures']['default']
            if shortname not in item_atlas:
                errors.append(f'{identifier} icon {shortname} missing from item_texture.json')
            else:
                png_ok(f'{rp}/{item_atlas[shortname]["textures"]}.png', 16, 16)
        for key in ('minecraft:damage', 'minecraft:durability', 'minecraft:max_stack_size'):
            if key not in components:
                warnings.append(f'{identifier} missing {key}')
        require_lang(f'item.{identifier}', identifier)

    for n in block_files:
        data = parsed[n]
        desc = data['minecraft:block']['description']
        identifier = desc['identifier']
        components = data['minecraft:block']['components']
        texture = components.get('minecraft:material_instances', {}).get('*', {}).get('texture')
        if not texture or texture not in terrain_atlas:
            errors.append(f'{identifier} block texture {texture} missing from terrain_texture.json')
        else:
            png_ok(f'{rp}/{terrain_atlas[texture]["textures"]}.png', 16, 16)
        light = components.get('minecraft:light_emission', 0)
        if not isinstance(light, int) or not 0 <= light <= 15:
            errors.append(f'{identifier} invalid light_emission {light}')
        require_lang(f'tile.{identifier}.name', identifier)

    for n in entity_files:
        data = parsed[n]
        desc = data['minecraft:entity']['description']
        identifier = desc['identifier']
        _, entity_id = identifier.split(':', 1)
        components = data['minecraft:entity']['components']
        for key in ('minecraft:health', 'minecraft:movement', 'minecraft:collision_box', 'minecraft:type_family'):
            if key not in components:
                errors.append(f'{identifier} missing {key}')
        if any(v is None for v in (components.get('minecraft:health', {}).get('value'), components.get('minecraft:collision_box', {}).get('width'))):
            errors.append(f'{identifier} has null numeric component')
        loot = components.get('minecraft:loot', {}).get('table')
        if loot and f'{bp}/{loot}' not in names:
            errors.append(f'{identifier} loot table {loot} missing')
        spawn = f'{bp}/spawn_rules/{entity_id}.json'
        if desc.get('is_spawnable') and spawn not in names:
            errors.append(f'{identifier} is spawnable but spawn rules are missing')
        if spawn in parsed:
            spawn_id = parsed[spawn]['minecraft:spawn_rules']['description']['identifier']
            if spawn_id != identifier:
                errors.append(f'Spawn rules identifier mismatch for {identifier}')
        client = f'{rp}/entity/{entity_id}.entity.json'
        geo = f'{rp}/models/entity/{entity_id}.geo.json'
        anim = f'{rp}/animations/{entity_id}.animation.json'
        rc = f'{rp}/render_controllers/{entity_id}.render_controllers.json'
        for path in (client, geo, anim, rc):
            if path not in names:
                errors.append(f'{identifier} missing {path}')
        if client in parsed:
            cdesc = parsed[client]['minecraft:client_entity']['description']
            if cdesc['identifier'] != identifier:
                errors.append(f'Client identifier mismatch for {identifier}')
            texture_path = cdesc.get('textures', {}).get('default')
            if texture_path:
                png_ok(f'{rp}/{texture_path}.png', 64, 64)
            geometry = cdesc.get('geometry', {}).get('default')
            if geo in parsed and geometry not in [g['description']['identifier'] for g in parsed[geo]['minecraft:geometry']]:
                errors.append(f'{identifier} geometry reference {geometry} missing')
            controller = cdesc.get('render_controllers', [None])[0]
            if rc in parsed and controller not in parsed[rc].get('render_controllers', {}):
                errors.append(f'{identifier} render controller {controller} missing')
            if anim in parsed:
                for animation in cdesc.get('animations', {}).values():
                    if animation not in parsed[anim].get('animations', {}):
                        errors.append(f'{identifier} animation {animation} missing')
            if 'spawn_egg' not in cdesc:
                errors.append(f'{identifier} missing spawn_egg')
        require_lang(f'entity.{identifier}.name', identifier)
        require_lang(f'item.spawn_egg.entity.{identifier}.name', identifier)

    for icon in (f'{bp}/pack_icon.png', f'{rp}/pack_icon.png'):
        png_ok(icon, 128, 128)

    print('Archive:', ARCHIVE)
    print('BP:', bp, '| RP:', rp)
    print('Items:', len(item_files), '| Blocks:', len(block_files), '| Entities:', len(entity_files))
    print('Files:', len(names), '| JSON:', len(json_files))
    print('Errors:', len(errors))
    for e in errors:
        print('  ERROR', e)
    print('Warnings:', len(warnings))
    for w in warnings[:20]:
        print('  WARN', w)
    sys.exit(1 if errors else 0)

